// ---------------------------------------------------------------------------
// Reads the uploaded CSV/TXT, sniffs the delimiter, finds the keyword column,
// carries through any volume/difficulty/CPC columns, dedupes, and splits the
// list into batches sized for a single OpenRouter call.
// ---------------------------------------------------------------------------

const cfg = $('Config').first().json;
const trigger = $('Telegram Trigger').first().json;
const doc = (trigger.message && trigger.message.document) || {};

let text = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  text = buf.toString('utf8');
} catch (err) {
  return [{ json: { ok: false, reason: 'The file could not be read from Telegram.', chatId: trigger.message.chat.id } }];
}
if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);

function sniffDelimiter(sample) {
  const candidates = [',', ';', '\t', '|'];
  const lines = sample.split('\n').slice(0, 6).filter((l) => l.trim() !== '');
  let best = ',';
  let bestScore = -1;
  for (const d of candidates) {
    const counts = lines.map((l) => l.split(d).length);
    if (!counts.length) continue;
    const avg = counts.reduce((a, b) => a + b, 0) / counts.length;
    const consistent = counts.every((c) => c === counts[0]);
    const score = (avg > 1 ? avg : 0) + (consistent ? 0.5 : 0);
    if (score > bestScore) { bestScore = score; best = d; }
  }
  return best;
}

// RFC4180 style parser: handles quoted fields, escaped quotes and embedded newlines.
function parseCsv(input, delim) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    if (inQuotes) {
      if (ch === '"') {
        if (input[i + 1] === '"') { field += '"'; i++; } else { inQuotes = false; }
      } else { field += ch; }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === delim) {
      row.push(field); field = '';
    } else if (ch === '\n') {
      row.push(field); rows.push(row); row = []; field = '';
    } else if (ch !== '\r') {
      field += ch;
    }
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows.filter((r) => r.some((c) => String(c).trim() !== ''));
}

const delimiter = sniffDelimiter(text);
const rows = parseCsv(text, delimiter);

if (!rows.length) {
  return [{ json: { ok: false, reason: 'The file appears to be empty.', chatId: trigger.message.chat.id } }];
}

const KEYWORD_HEADERS = ['keyword', 'keywords', 'query', 'queries', 'term', 'terms', 'search term', 'search query', 'kw', 'phrase'];
const VOLUME_RE = /volume|searches|msv|^vol$/i;
const DIFFICULTY_RE = /difficult|^kd$|competition|^comp$/i;
const CPC_RE = /cpc|cost.?per.?click/i;

const first = rows[0].map((c) => String(c).trim());
const lowerFirst = first.map((c) => c.toLowerCase());
const hasHeader = lowerFirst.some((c) =>
  KEYWORD_HEADERS.includes(c) || VOLUME_RE.test(c) || DIFFICULTY_RE.test(c) || CPC_RE.test(c));

let keywordCol = 0;
let volumeCol = -1;
let difficultyCol = -1;
let cpcCol = -1;

if (hasHeader) {
  const kwIdx = lowerFirst.findIndex((c) => KEYWORD_HEADERS.includes(c));
  keywordCol = kwIdx === -1 ? 0 : kwIdx;
  volumeCol = lowerFirst.findIndex((c) => VOLUME_RE.test(c));
  difficultyCol = lowerFirst.findIndex((c) => DIFFICULTY_RE.test(c));
  cpcCol = lowerFirst.findIndex((c) => CPC_RE.test(c));
}

const dataRows = hasHeader ? rows.slice(1) : rows;

const seen = new Set();
const keywords = [];
const extras = {};
let skipped = 0;

for (const r of dataRows) {
  const kw = String(r[keywordCol] === undefined ? '' : r[keywordCol]).trim().replace(/\s+/g, ' ');
  if (!kw || kw.length > 120 || /^[\d.,%$-]+$/.test(kw)) { skipped++; continue; }
  const key = kw.toLowerCase();
  if (seen.has(key)) { skipped++; continue; }
  seen.add(key);
  keywords.push(kw);
  const extra = {};
  if (volumeCol > -1 && r[volumeCol] !== undefined) extra.volume = String(r[volumeCol]).trim();
  if (difficultyCol > -1 && r[difficultyCol] !== undefined) extra.difficulty = String(r[difficultyCol]).trim();
  if (cpcCol > -1 && r[cpcCol] !== undefined) extra.cpc = String(r[cpcCol]).trim();
  if (Object.keys(extra).length) extras[key] = extra;
}

const maxKeywords = Number(cfg.maxKeywords) || 1000;
let capped = false;
let finalKeywords = keywords;
if (finalKeywords.length > maxKeywords) {
  finalKeywords = finalKeywords.slice(0, maxKeywords);
  capped = true;
}

if (!finalKeywords.length) {
  return [{ json: {
    ok: false,
    reason: 'No usable keywords were found. Check that the file has a keyword column with text values.',
    chatId: trigger.message.chat.id,
  } }];
}

const batchSize = Number(cfg.batchSize) || 40;
const batches = [];
for (let i = 0; i < finalKeywords.length; i += batchSize) {
  batches.push(finalKeywords.slice(i, i + batchSize));
}

const resultSchema = {
  type: 'object',
  additionalProperties: false,
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['keyword', 'intent', 'funnel_stage', 'cluster_label', 'content_format', 'priority', 'is_branded', 'is_local', 'notes'],
        properties: {
          keyword: { type: 'string', description: 'Echo the keyword back exactly as supplied.' },
          intent: { type: 'string', enum: ['informational', 'navigational', 'commercial', 'transactional'] },
          funnel_stage: { type: 'string', enum: ['awareness', 'consideration', 'decision'] },
          cluster_label: { type: 'string', description: 'Two to four word topic label shared by every keyword on the same subject.' },
          content_format: { type: 'string', enum: ['blog post', 'how-to guide', 'tutorial', 'listicle', 'comparison page', 'review page', 'product page', 'category page', 'landing page', 'pricing page', 'FAQ', 'glossary', 'case study', 'location page', 'tool or calculator'] },
          priority: { type: 'string', enum: ['high', 'medium', 'low'] },
          is_branded: { type: 'boolean' },
          is_local: { type: 'boolean' },
          notes: { type: 'string', description: 'Under twelve words, or an empty string.' },
        },
      },
    },
  },
};

const systemPrompt = [
  'You are a senior SEO strategist classifying search intent for content planning.',
  '',
  'For every keyword supplied, return one result object. Return exactly as many results as keywords, in the same order, echoing each keyword back verbatim. Emit no prose outside the JSON.',
  '',
  'Intent definitions:',
  '- informational: the searcher wants to understand something. No purchase decision is being made yet.',
  '- navigational: the searcher is looking for a specific site, brand, product name or login page.',
  '- commercial: the searcher is comparing, evaluating or researching before buying. Includes best, vs, review, alternative and top style queries.',
  '- transactional: the searcher is ready to act. Includes buy, price, quote, near me, hire, book and free trial style queries.',
  '',
  'Rules:',
  '1. cluster_label groups keywords that would be served by the same page or the same tight topic. Reuse the exact same label string across every keyword in that group. Do not invent a separate label for a near duplicate phrasing.',
  '2. Keep cluster labels short, lowercase and descriptive of the topic, not the intent. Good: "wordpress hosting cost". Bad: "transactional hosting queries".',
  '3. content_format must be the format that would realistically rank for that query, not the format you would prefer to write.',
  '4. priority reflects commercial value and specificity together. A vague head term with no clear intent is not high priority just because it is popular.',
  '5. is_local is true only when the query implies a geographic service area, including "near me" and city or region modifiers.',
  '6. is_branded is true when a specific company, product or trademark name appears.',
  '7. notes is optional context a content planner would act on, such as a SERP feature opportunity or an ambiguity. Leave it empty rather than padding it.',
].join('\n');

return batches.map((batch, i) => ({
  json: {
    ok: true,
    chatId: trigger.message.chat.id,
    fileName: doc.file_name || 'keywords.csv',
    batchIndex: i,
    batchCount: batches.length,
    totalKeywords: finalKeywords.length,
    skipped: skipped,
    capped: capped,
    delimiter: delimiter === '\t' ? 'tab' : delimiter,
    hasHeader: hasHeader,
    keywords: batch,
    extras: i === 0 ? extras : {},
    payload: {
      model: cfg.model,
      models: [cfg.model, cfg.fallbackModel],
      temperature: Number(cfg.temperature),
      max_tokens: 8000,
      response_format: { type: 'json_schema', json_schema: { name: 'keyword_intent', strict: true, schema: resultSchema } },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: 'Classify these ' + batch.length + ' keywords:\n\n' + batch.map((k, n) => (n + 1) + '. ' + k).join('\n') },
      ],
    },
  },
}));

// ---------------------------------------------------------------------------
// Merges every batch response back onto the original keyword list by matching
// on the keyword string rather than item index, so a failed or partial batch
// degrades into "unclassified" rows instead of corrupting the alignment.
// Then builds the second pass payload that consolidates cluster labels.
// ---------------------------------------------------------------------------

const cfg = $('Config').first().json;
const batchItems = $('Parse Keyword File').all().map((i) => i.json);
const meta = batchItems[0] || {};
const extras = meta.extras || {};

const allKeywords = [];
for (const b of batchItems) for (const k of (b.keywords || [])) allKeywords.push(k);

function messageText(r) {
  const choice = r && r.choices && r.choices[0];
  const content = choice && choice.message ? choice.message.content : '';
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) return content.map((p) => p.text || '').join('');
  return '';
}

function safeParse(str) {
  let raw = String(str || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try { return JSON.parse(raw); } catch (e) { /* fall through */ }
  const s = raw.indexOf('{');
  const t = raw.lastIndexOf('}');
  if (s !== -1 && t > s) { try { return JSON.parse(raw.slice(s, t + 1)); } catch (e) { return null; } }
  return null;
}

const byKeyword = new Map();
let usage = 0;
let modelUsed = cfg.model;

for (const item of $input.all()) {
  const res = item.json || {};
  if (res.usage && res.usage.total_tokens) usage += res.usage.total_tokens;
  if (res.model) modelUsed = res.model;
  const parsed = safeParse(messageText(res));
  const results = parsed && Array.isArray(parsed.results) ? parsed.results : [];
  for (const r of results) {
    if (!r || !r.keyword) continue;
    byKeyword.set(String(r.keyword).trim().toLowerCase(), r);
  }
}

const classified = allKeywords.map((kw) => {
  const hit = byKeyword.get(kw.toLowerCase());
  const extra = extras[kw.toLowerCase()] || {};
  return {
    keyword: kw,
    intent: hit ? hit.intent : 'unclassified',
    funnel_stage: hit ? hit.funnel_stage : '',
    cluster_label: hit ? String(hit.cluster_label || '').trim().toLowerCase() : 'unclassified',
    content_format: hit ? hit.content_format : '',
    priority: hit ? hit.priority : '',
    is_branded: hit ? !!hit.is_branded : false,
    is_local: hit ? !!hit.is_local : false,
    notes: hit ? (hit.notes || '') : 'Not returned by the model',
    volume: extra.volume || '',
    difficulty: extra.difficulty || '',
    cpc: extra.cpc || '',
  };
});

// Collect the raw labels with a couple of example keywords each, so pass two
// can merge near duplicates like "seo pricing" and "seo cost" into one cluster.
const labelExamples = {};
for (const c of classified) {
  if (!c.cluster_label || c.cluster_label === 'unclassified') continue;
  if (!labelExamples[c.cluster_label]) labelExamples[c.cluster_label] = [];
  if (labelExamples[c.cluster_label].length < 3) labelExamples[c.cluster_label].push(c.keyword);
}
const rawLabels = Object.keys(labelExamples);

const clusterSchema = {
  type: 'object',
  additionalProperties: false,
  required: ['clusters'],
  properties: {
    clusters: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['canonical_label', 'merged_from', 'pillar_page_title'],
        properties: {
          canonical_label: { type: 'string', description: 'Short lowercase label for the merged cluster.' },
          merged_from: { type: 'array', items: { type: 'string' }, description: 'Every raw label that maps to this cluster, copied verbatim.' },
          pillar_page_title: { type: 'string', description: 'A publishable title for the page or hub that would own this cluster.' },
        },
      },
    },
  },
};

const payload = {
  model: cfg.model,
  models: [cfg.model, cfg.fallbackModel],
  temperature: Number(cfg.temperature),
  max_tokens: 4000,
  response_format: { type: 'json_schema', json_schema: { name: 'cluster_consolidation', strict: true, schema: clusterSchema } },
  messages: [
    {
      role: 'system',
      content: [
        'You are consolidating topic cluster labels produced independently across several batches, so near duplicates need merging.',
        '',
        'Rules:',
        '1. Every raw label supplied must appear in exactly one merged_from array. Copy labels verbatim, including spacing.',
        '2. Merge two labels only when a single page could realistically serve both. Do not merge distinct intents or distinct products just because the wording is similar.',
        '3. A label with no good match stays on its own with merged_from containing only itself.',
        '4. canonical_label should be the clearest of the merged labels, or a better short label if none of them is clear.',
        '5. pillar_page_title should read like a real page title, not a keyword string.',
      ].join('\n'),
    },
    {
      role: 'user',
      content: 'Consolidate these ' + rawLabels.length + ' cluster labels.\n\n' +
        rawLabels.map((l) => '- ' + l + '  (examples: ' + labelExamples[l].join('; ') + ')').join('\n'),
    },
  ],
};

return [{ json: {
  chatId: meta.chatId,
  fileName: meta.fileName,
  totalKeywords: classified.length,
  skipped: meta.skipped || 0,
  capped: !!meta.capped,
  batchCount: meta.batchCount || 1,
  batchesReturned: $input.all().length,
  tokensUsed: usage,
  modelUsed: modelUsed,
  rawLabelCount: rawLabels.length,
  classified: classified,
  payload: payload,
} }];

// ---------------------------------------------------------------------------
// Applies the canonical cluster mapping from pass two, then emits one clean
// spreadsheet row per keyword. If pass two failed, the raw labels are kept.
// ---------------------------------------------------------------------------

const collected = $('Collect Classifications').first().json;
const res = $json || {};

function messageText(r) {
  const choice = r && r.choices && r.choices[0];
  const content = choice && choice.message ? choice.message.content : '';
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) return content.map((p) => p.text || '').join('');
  return '';
}

let mapping = {};
let pillars = {};
let consolidated = false;

try {
  let raw = messageText(res).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  let parsed = null;
  try { parsed = JSON.parse(raw); } catch (e) {
    const s = raw.indexOf('{'); const t = raw.lastIndexOf('}');
    if (s !== -1 && t > s) parsed = JSON.parse(raw.slice(s, t + 1));
  }
  if (parsed && Array.isArray(parsed.clusters)) {
    for (const c of parsed.clusters) {
      const canon = String(c.canonical_label || '').trim().toLowerCase();
      if (!canon) continue;
      for (const from of (c.merged_from || [])) {
        mapping[String(from).trim().toLowerCase()] = canon;
      }
      pillars[canon] = c.pillar_page_title || '';
    }
    consolidated = Object.keys(mapping).length > 0;
  }
} catch (e) {
  consolidated = false;
}

const INTENT_ORDER = { transactional: 0, commercial: 1, informational: 2, navigational: 3, unclassified: 4 };
const PRIORITY_ORDER = { high: 0, medium: 1, low: 2, '': 3 };

const rows = collected.classified.map((c) => {
  const cluster = mapping[c.cluster_label] || c.cluster_label;
  return {
    Keyword: c.keyword,
    Cluster: cluster,
    'Pillar Page': pillars[cluster] || '',
    Intent: c.intent,
    'Funnel Stage': c.funnel_stage,
    'Content Format': c.content_format,
    Priority: c.priority,
    Branded: c.is_branded ? 'yes' : 'no',
    Local: c.is_local ? 'yes' : 'no',
    'Search Volume': c.volume,
    Difficulty: c.difficulty,
    CPC: c.cpc,
    Notes: c.notes,
  };
});

// Group the sheet by cluster, with the highest value clusters first, so the
// file is readable top to bottom without any sorting in Excel.
const clusterScore = {};
for (const r of rows) {
  const s = clusterScore[r.Cluster] || { size: 0, best: 9 };
  s.size += 1;
  s.best = Math.min(s.best, PRIORITY_ORDER[r.Priority] === undefined ? 3 : PRIORITY_ORDER[r.Priority]);
  clusterScore[r.Cluster] = s;
}

rows.sort((a, b) => {
  const sa = clusterScore[a.Cluster];
  const sb = clusterScore[b.Cluster];
  if (sa.best !== sb.best) return sa.best - sb.best;
  if (sa.size !== sb.size) return sb.size - sa.size;
  if (a.Cluster !== b.Cluster) return a.Cluster < b.Cluster ? -1 : 1;
  const ia = INTENT_ORDER[a.Intent] === undefined ? 5 : INTENT_ORDER[a.Intent];
  const ib = INTENT_ORDER[b.Intent] === undefined ? 5 : INTENT_ORDER[b.Intent];
  if (ia !== ib) return ia - ib;
  return a.Keyword < b.Keyword ? -1 : 1;
});

return rows.map((r) => ({ json: r, pairedItem: { item: 0 } }));

// ---------------------------------------------------------------------------
// Rebuilds a Telegram readable overview from the finished rows, so the sender
// gets the headline findings without opening the spreadsheet.
// ---------------------------------------------------------------------------

const rows = $('Build Rows').all().map((i) => i.json);
const collected = $('Collect Classifications').first().json;

function esc(v) {
  return String(v === undefined || v === null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const ICON = { transactional: '\u{1F4B0}', commercial: '\u{1F50E}', informational: '\u{1F4D8}', navigational: '\u{1F9ED}', unclassified: '\u2753' };
const PRIORITY_ORDER = { high: 0, medium: 1, low: 2 };

const intentCounts = {};
const priorityCounts = {};
const clusters = {};
let localCount = 0;
let brandedCount = 0;

for (const r of rows) {
  intentCounts[r.Intent] = (intentCounts[r.Intent] || 0) + 1;
  if (r.Priority) priorityCounts[r.Priority] = (priorityCounts[r.Priority] || 0) + 1;
  if (r.Local === 'yes') localCount++;
  if (r.Branded === 'yes') brandedCount++;
  const c = clusters[r.Cluster] || { size: 0, best: 9, pillar: r['Pillar Page'], intents: {} };
  c.size += 1;
  const p = PRIORITY_ORDER[r.Priority];
  c.best = Math.min(c.best, p === undefined ? 3 : p);
  c.intents[r.Intent] = (c.intents[r.Intent] || 0) + 1;
  if (!c.pillar && r['Pillar Page']) c.pillar = r['Pillar Page'];
  clusters[r.Cluster] = c;
}

const ranked = Object.entries(clusters)
  .filter((e) => e[0] !== 'unclassified')
  .sort((a, b) => (a[1].best - b[1].best) || (b[1].size - a[1].size))
  .slice(0, 8);

const lines = [];
lines.push('<b>Keyword Intent Clusters</b>');
lines.push('<i>' + esc(collected.fileName) + ' \u00B7 ' + rows.length + ' keywords \u00B7 ' +
  Object.keys(clusters).length + ' clusters</i>');
lines.push('');

lines.push('<b>Intent mix</b>');
for (const key of ['transactional', 'commercial', 'informational', 'navigational', 'unclassified']) {
  if (!intentCounts[key]) continue;
  const pct = Math.round((intentCounts[key] / rows.length) * 100);
  lines.push(ICON[key] + ' ' + esc(key) + ': ' + intentCounts[key] + ' (' + pct + '%)');
}
lines.push('');

lines.push('<b>Start here</b>');
ranked.forEach((entry, i) => {
  const name = entry[0];
  const c = entry[1];
  lines.push((i + 1) + '. <b>' + esc(name) + '</b> \u00B7 ' + c.size + ' kw' +
    (c.best === 0 ? ' \u00B7 high priority' : ''));
  if (c.pillar) lines.push('    <i>' + esc(c.pillar) + '</i>');
});
lines.push('');

function plural(n, one, many) { return n + ' ' + (n === 1 ? one : many); }

const flags = [];
if (priorityCounts.high) flags.push(plural(priorityCounts.high, 'high priority keyword', 'high priority keywords'));
if (localCount) flags.push(plural(localCount, 'local intent keyword', 'local intent keywords'));
if (brandedCount) flags.push(plural(brandedCount, 'branded keyword', 'branded keywords'));
if (collected.skipped) flags.push(plural(collected.skipped, 'row skipped as a duplicate or blank', 'rows skipped as duplicates or blanks'));
if (collected.capped) flags.push('list was capped at the configured maximum');
if (collected.batchesReturned < collected.batchCount) {
  const failed = collected.batchCount - collected.batchesReturned;
  flags.push(plural(failed, 'batch failed', 'batches failed') + ', those keywords are marked unclassified');
}
if (flags.length) {
  lines.push('<b>Worth knowing</b>');
  for (const f of flags) lines.push('\u2022 ' + esc(f));
  lines.push('');
}

lines.push('<i>' + esc(collected.modelUsed) + ' \u00B7 ' + collected.tokensUsed + ' tokens</i>');

let text = lines.join('\n');
if (text.length > 3800) text = text.slice(0, 3780) + '\n<i>[trimmed]</i>';

return [{ json: { chatId: collected.chatId, summary: text } }];
